cd "/Users/joshuaf/Documents/Claude/02_PROJECTS/main-conclusion-bootcamp" && echo "=== components from parity map check ===" && python3 -c "
import json, re
with open('docs/parity/CONTENT_PARITY_MAP.json') as f: pm = json.load(f)
components = set()
for entry in pm['entries']:
    for c in entry.get('components', []):
        # extract bare component name
        m = re.search(r'([A-Z][A-Za-z0-9_]+)\.tsx', c)
        if m: components.add(m.group(1))
        else:
            # for paths like 'persistence/Persistence.ts' get filename stem
            m2 = re.search(r'([A-Z][A-Za-z0-9_]+)\.ts', c)
            if m2: components.add(m2.group(1))
print(f'parity-map distinct components: {len(components)}')
with open('docs/architecture-plan.md') as f: arch = f.read()
missing = sorted(c for c in components if c not in arch)
print(f'missing from architecture-plan.md: {len(missing)}')
for m in missing: print(' -', m)
"

cd "/Users/joshuaf/Documents/Claude/02_PROJECTS/main-conclusion-bootcamp" && python3 -c "
import json, re
with open('docs/parity/CONTENT_PARITY_MAP.json') as f: pm = json.load(f)
routes = set()
for entry in pm['entries']:
    r = entry.get('route', '')
    if r and r.startswith('/'):
        routes.add(r.split(' ')[0])
with open('docs/architecture-plan.md') as f: arch = f.read()

# Build pattern coverage from architecture plan
# Look for route declarations: { path: 'x' or { path: ':id'
covered_patterns = set()
for m in re.finditer(r\"path: '([^']+)'\", arch):
    covered_patterns.add(m.group(1))

def is_covered(route, arch):
    # 1) literal match
    if route in arch: return ('literal', None)
    # 2) parameterized: /lessons/1.7 → :lessonId, /simulator/trap-master/T1 → :traitId
    parts = route.lstrip('/').split('/')
    # check each parent path in route map structure
    # also: route is covered if its terminal segment matches a :param under matching parent
    candidates = {
        ':lessonId': ('lessons',),
        ':drillId': ('drills',),
        ':sectionId': ('hard-sentences',),
        ':traitId': ('simulator','trap-master'),
        ':toolId': ('reference','named-tools'),
    }
    for param, parents in candidates.items():
        if len(parts) >= len(parents)+1:
            if tuple(parts[:len(parents)]) == parents and param in covered_patterns:
                return ('param', param)
    return ('missing', None)

missing_for_real = []
for r in sorted(routes):
    status, _ = is_covered(r, arch)
    if status == 'missing': missing_for_real.append(r)

print(f'routes total: {len(routes)}')
print(f'genuinely missing after parameterized-route accounting: {len(missing_for_real)}')
for m in missing_for_real: print(' -', m)
"

