@import './tokens.css';
@tailwind base;
@tailwind components;
@tailwind utilities;

/* Reset + base */
*, *::before, *::after { box-sizing: border-box; }
html, body, #root { height: 100%; }

body {
  font-family: 'Outfit', 'Inter', system-ui, sans-serif;
  font-size: var(--t-body);
  line-height: 1.6;
  background: rgb(var(--bg));
  color: rgb(var(--ink));
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

/* Lesson prose — register 2 lives in serif (spec §3.1.2 voice-to-typography rule) */
.lesson-prose {
  font-family: ui-serif, 'Iowan Old Style', 'Apple Garamond', Georgia, serif;
  font-size: var(--t-body-prose);
  line-height: 1.7;
  max-width: 64ch;
}
.lesson-prose p + p { margin-top: var(--s-4); }
.lesson-prose strong, .lesson-prose b { font-weight: 600; color: rgb(var(--ink)); }
.lesson-prose em { font-style: italic; }

/* Named-tool inline callout — Register 1 mono badge */
.named-tool-inline {
  font-family: 'JetBrains Mono', ui-monospace, SFMono-Regular, monospace;
  font-size: var(--t-mono);
  font-weight: 600;
  letter-spacing: 0.04em;
  color: rgb(var(--accent));
  text-transform: none;
  padding: 1px 6px;
  border-radius: var(--r-2);
  background: rgb(var(--accent) / 0.10);
  cursor: pointer;
  transition: background var(--d-fast) var(--ease);
}
.named-tool-inline:hover { background: rgb(var(--accent) / 0.16); }
.named-tool-inline:focus-visible {
  outline: 2px solid rgb(var(--accent));
  outline-offset: 2px;
}

/* Focus ring (spec §3.7.2: 2px gold outline + 2px offset) */
:focus-visible {
  outline: 2px solid rgb(var(--accent));
  outline-offset: 2px;
  border-radius: var(--r-2);
}

/* Selection */
::selection {
  background: rgb(var(--accent) / 0.28);
  color: rgb(var(--ink));
}

/* Skip link (spec §3.7.2) */
.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: rgb(var(--accent));
  color: rgb(var(--bg));
  padding: var(--s-2) var(--s-4);
  border-radius: var(--r-3);
  font-weight: 600;
  z-index: 100;
}
.skip-link:focus { left: var(--s-4); top: var(--s-4); }

