import { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import lessons from '@/data/lessons.generated.json';
import { useUser, STUB_USER_ID_EXPORT } from '@/hooks/useUser';
import { useModuleProgress } from '@/hooks/useModuleProgress';
import { getPersistence } from '@/persistence/factory';
import { TABLES, LessonProgress } from '@/persistence/records';
import { newId, now } from '@/lib/ids';
import { useDrawer } from '@/components/workspace-shell/WorkspaceShell';
import { CakeOnBlocks } from '@/components/argument-structure-map/CakeOnBlocks';
import type { LessonId, NamedToolId, ReferenceId } from '@/types/source-slots';

interface LessonData {
  id: LessonId;
  number: string;
  title: string;
  hook: string;
  prose_blocks: Array<
    | { kind: 'p'; text: string }
    | { kind: 'callout'; label: string; body: string }
    | { kind: 'example'; tag: string; body: string }
    | { kind: 'visual-spec'; component: 'CakeOnBlocks'; caption: string }
  >;
  named_tool_callouts: Array<{ tool_id: NamedToolId; appears_in_paragraph: number }>;
  reference_callouts: Array<{ reference_id: ReferenceId; label: string }>;
  checkpoint: {
    prompt: string;
    options: Array<{ id: string; text: string; correct: boolean; reveal: string }>;
  };
  sources: string[];
}

export function Lesson(): JSX.Element {
  const { lessonId: routeId } = useParams<{ lessonId: string }>();
  const data = (lessons as LessonData[]).find((l) => l.number === routeId);
  const user = useUser();
  const { progress, markLessonComplete } = useModuleProgress();
  const drawer = useDrawer();
  const [checkpointPicked, setCheckpointPicked] = useState<string | null>(null);

  // Persistence write — Layer 8.
  useEffect(() => {
    if (!data || !user) return;
    (async () => {
      const persist = getPersistence(STUB_USER_ID_EXPORT);
      const id = newId();
      const rec = LessonProgress.parse({
        id,
        user_id: STUB_USER_ID_EXPORT,
        lesson_id: data.id,
        viewed_at: now(),
      });
      await persist.set(TABLES.lesson_progress, id, rec);
    })();
  }, [data, user]);

  if (!data) {
    return (
      <div className="px-6 py-12 max-w-prose mx-auto">
        <div className="font-mono text-label uppercase tracking-wider text-ink-faint">Not found</div>
        <h1 className="font-serif text-h1 mt-2">Lesson {routeId} not in v1.</h1>
        <Link to="/lessons" className="text-accent font-mono text-mono mt-4 inline-block">← Back to Lessons</Link>
      </div>
    );
  }

  const checkpointOption = data.checkpoint.options.find((o) => o.id === checkpointPicked);

  async function handleMarkComplete() {
    if (!data) return;
    await markLessonComplete(data.id, `/lessons/${data.number}`);
  }

  const completed = progress?.completed_lessons.includes(data.id) ?? false;

  return (
    <article className="px-6 py-10 desktop:px-12 desktop:py-14 max-w-[840px] mx-auto" data-lesson-id={data.id}>
      {/* Layer 1 — Route header */}
      <header className="mb-8">
        <div className="flex items-center gap-3">
          <span className="font-mono text-mono uppercase tracking-wider text-accent">Lesson {data.number}</span>
          <span className="font-mono text-label uppercase tracking-wider text-ink-faint">{data.id}</span>
