        <p className="font-serif text-h3 mt-3 text-ink-soft italic">{data.hook}</p>
      </header>

      {/* Layer 2 — Register-2 prose with inline named-tool + reference callouts */}
      <div className="lesson-prose">
        {data.prose_blocks.map((block, i) => {
          if (block.kind === 'p') {
            return <ProseParagraph key={i} text={block.text} drawer={drawer} />;
          }
          if (block.kind === 'callout') {
            return (
              <aside key={i} className="my-6 px-5 py-4 rounded-3 border-l-2 border-accent bg-[rgb(var(--accent)/0.06)]">
                <div className="font-mono text-label uppercase tracking-wider text-accent mb-2">{block.label}</div>
                <div className="font-serif text-body-prose text-ink" dangerouslySetInnerHTML={{ __html: block.body }} />
              </aside>
            );
          }
          if (block.kind === 'example') {
            // Layer 3 — guided example
            return (
              <aside key={i} className="my-6 px-5 py-4 rounded-3 bg-surface border border-[rgb(var(--border)/0.08)]">
                <div className="font-mono text-label uppercase tracking-wider text-ink-faint mb-2">{block.tag}</div>
                <div className="font-serif text-body-prose" dangerouslySetInnerHTML={{ __html: block.body }} />
              </aside>
            );
          }
          if (block.kind === 'visual-spec') {
            // Layer 7 — CakeOnBlocks SVG
            return (
              <div key={i} className="my-8">
                <CakeOnBlocks />
                <p className="font-mono text-mono text-ink-faint text-center mt-2">{block.caption}</p>
