                      : 'border-[rgb(var(--border)/0.08)] hover:border-[rgb(var(--accent)/0.4)] hover:bg-surface',
                  ].join(' ')}
                >
                  <span className="font-mono text-mono text-ink-faint mr-3">{opt.id}</span>
                  <span className="text-body">{opt.text}</span>
                  {showVerdict && (
                    <div className={[
                      'mt-2 font-mono text-mono',
                      opt.correct ? 'text-role-conclusion' : 'text-error',
