              <button
                key={ref.reference_id}
                type="button"
                className="px-3 py-1.5 rounded-2 border border-[rgb(var(--border)/0.08)] hover:bg-surface font-mono text-mono text-ink-soft hover:text-ink transition-colors duration-150 ease-eased"
                onClick={() => drawer.open({ mode: 'reference', reference_id: ref.reference_id })}
              >
                {ref.label}
              </button>
            ))}
          </div>
        </section>
      )}

      {/* Source citation — handoff §6 SBSR */}
      <footer className="mt-12 pt-6 border-t border-[rgb(var(--border)/0.08)]">
        <div className="font-mono text-label uppercase tracking-wider text-ink-faint mb-2">Sources</div>
