      </section>

      {/* Layer 5 — Named-tool quick callouts (lateral access to the lexicon) */}
      {data.named_tool_callouts.length > 0 && (
        <section className="mt-10">
          <div className="font-mono text-label uppercase tracking-wider text-ink-faint mb-3">Named tools used here</div>
