            ))}
          </div>
        </section>
      )}

      {/* Layer 6 — Reference quick callouts (drawer overlay, no URL change) */}
      {data.reference_callouts.length > 0 && (
        <section className="mt-6">
          <div className="font-mono text-label uppercase tracking-wider text-ink-faint mb-3">Open in reference</div>
          <div className="flex flex-wrap gap-2">
            {data.reference_callouts.map((ref) => (
              <button
                key={ref.reference_id}
                type="button"
                className="px-3 py-1.5 rounded-2 border border-[rgb(var(--border)/0.08)] hover:bg-surface font-mono text-mono text-ink-soft hover:text-ink transition-colors duration-150 ease-eased"
