// scripts/import-content.ts
//
// Build-time corpus import script (per architecture-plan.md §4 + Gate 1 G1.9).
//
// CURRENT STATE: Gate 4 Step 1 — DRY-IMPORT SMOKE TEST.
// This file is the skeleton + smoke-test entry point. The full pipeline (vision-model
// OCR for image-only PDFs, DOCX via mammoth, manifest emission, parity check) is
// authored incrementally as Module 1 build progresses.
//
// Smoke-test target (2026-04-30):
//   Homework/AP Answer Key (1).pdf
// Three checks, per Joshua's Step 1 directive:
//   (a) ≥6 numbered items present (G3.M1.13-AP-PARTITION assumes it)
//   (b) text-extractability / OCR confidence on this S-tier file
//   (c) typed-record schema fits real extracted output
//
// Run (after Step 2 scaffolding):
//   npm run import -- --smoke ap-answer-key
//
// Source paths reference the canonical /Curriculum/ tree; never copy in-repo (G1.9).

import { z } from 'zod';

// ─────────────────────────────────────────────────────────────────────────────
// Schemas (extracted to src/content/schemas.ts in Step 2; inlined here for the
// smoke test so this file is self-contained).
// ─────────────────────────────────────────────────────────────────────────────

const ClaimRoleTag = z.enum([
  'Background',
  'Opposing-Viewpoint',
  'Concession',
  'Premise',
  'Supporting-Premise',
  'Intermediate-Conclusion',
  'Main-Conclusion',
  'Pivot',
  'Unknown',
]);
type ClaimRoleTag = z.infer<typeof ClaimRoleTag>;

const ArgumentClaim = z.object({
  claim_number: z.number().int().min(1),
  text: z.string().min(10),
  role: ClaimRoleTag.default('Unknown'),
});

const APAnswerKeyItem = z.object({
  item_number: z.number().int(),                         // file uses 2..9; partition rule references this
  stimulus: z.string().min(40),
  claims: z.array(ArgumentClaim),                         // may be empty for stimulus-only entries
  has_full_breakdown: z.boolean(),                        // false for items with stimulus only (e.g., item 7)
  source_anchor: z.object({
    file: z.literal('Homework/AP Answer Key (1).pdf'),
    page: z.number().int().min(1).max(4),
  }),
});

type APAnswerKeyItem = z.infer<typeof APAnswerKeyItem>;

// ─────────────────────────────────────────────────────────────────────────────
// PDF parse — native text extraction first; vision-model OCR fallback on
// confidence < 0.85 or empty page text. AP Answer Key (1).pdf turns out to be
// text-extractable directly; smoke-test path doesn't exercise vision-model OCR.
// ─────────────────────────────────────────────────────────────────────────────

async function extractTextFromPdf(_path: string): Promise<{ pages: string[]; ocrUsed: boolean; minConfidence: number }> {
  // Step 2 wires pdfjs-dist + the @anthropic-ai vision-model OCR fallback.
  // For the Step 1 smoke test the result is precomputed from the Gate 4
