import { useEffect, useState } from 'react';
import { getPersistence } from '@/persistence/factory';
import { TABLES, User } from '@/persistence/records';
import { newId, now } from '@/lib/ids';

const STUB_USER_ID = '00000000-0000-4000-8000-000000000001';

export function useUser(): User | null {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const persist = getPersistence(STUB_USER_ID);
      let existing = await persist.get<User>(TABLES.users, STUB_USER_ID);
      if (!existing) {
        existing = User.parse({
          id: STUB_USER_ID,
          name: 'Student',
          started_at: now(),
          last_seen: now(),
          settings: {},
        });
        await persist.set(TABLES.users, STUB_USER_ID, existing);
      } else {
        existing = { ...existing, last_seen: now() };
        await persist.set(TABLES.users, STUB_USER_ID, existing);
      }
      if (!cancelled) setUser(existing);
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  return user;
}

export const STUB_USER_ID_EXPORT = STUB_USER_ID;

/**
 * Module progress hook — backs the LockedRoute / unlock cascade per §5.
 */

import { useCallback, useEffect, useState } from 'react';
import { getPersistence } from '@/persistence/factory';
import { TABLES, ModuleProgress } from '@/persistence/records';
import { newId, now } from '@/lib/ids';
import { INITIAL_UNLOCKED_ROUTES, unlockNext, type ProgressShape } from '@/lib/ordering';
import { STUB_USER_ID_EXPORT } from './useUser';

const PROGRESS_ID = '00000000-0000-4000-8000-000000000010';

export function useModuleProgress(): {
  progress: ModuleProgress | null;
  markRouteVisited: (routeId: string) => Promise<void>;
  markLessonComplete: (lessonId: string, routeId: string) => Promise<void>;
} {
  const [progress, setProgress] = useState<ModuleProgress | null>(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const persist = getPersistence(STUB_USER_ID_EXPORT);
      let existing = await persist.get<ModuleProgress>(TABLES.module_progress, PROGRESS_ID);
      if (!existing) {
        existing = ModuleProgress.parse({
          id: PROGRESS_ID,
          user_id: STUB_USER_ID_EXPORT,
          unlocked_modules: ['M1', 'M2', 'M3', 'M5', 'M6'],
          unlocked_routes: INITIAL_UNLOCKED_ROUTES,
          completed_lessons: [],
          completed_drills: [],
          completed_capstones: [],
          updated_at: now(),
        });
        await persist.set(TABLES.module_progress, PROGRESS_ID, existing);
      }
      if (!cancelled) setProgress(existing);
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const markRouteVisited = useCallback(async (_routeId: string) => {
    // Reserved for analytics in Module 6.
  }, []);

  const markLessonComplete = useCallback(
    async (lessonId: string, routeId: string) => {
      const persist = getPersistence(STUB_USER_ID_EXPORT);
      const current = await persist.get<ModuleProgress>(TABLES.module_progress, PROGRESS_ID);
      const base = current ?? progress;
      if (!base) return;
      const completed = base.completed_lessons.includes(lessonId)
        ? base.completed_lessons
        : [...base.completed_lessons, lessonId];
      const shape: ProgressShape = {
        unlocked_routes: base.unlocked_routes,
        completed_lessons: completed,
        completed_drills: base.completed_drills,
      };
      const additions = unlockNext(routeId, shape);
      const merged: ModuleProgress = {
        ...base,
        completed_lessons: completed,
        unlocked_routes: Array.from(new Set([...base.unlocked_routes, ...additions])),
        updated_at: now(),
      };
      await persist.set(TABLES.module_progress, PROGRESS_ID, merged);
      setProgress(merged);
    },
    [progress],
  );

  return { progress, markRouteVisited, markLessonComplete };
}

