  // Find label (case-insensitive, allow optional colon), capture until any nextLabel.
  const labelRe = new RegExp(`(?:^|\\n)\\s*${label}\\s*:?\\s*\\n?`, 'i');
  const m = text.match(labelRe);
  if (!m) return '';
  const start = m.index! + m[0].length;
  let end = text.length;
  for (const nl of nextLabels) {
    const re = new RegExp(`\\n\\s*${nl}\\s*:?\\s*\\n`, 'i');
    const nm = text.slice(start).match(re);
