/**
 * Generic Reference section shell, populated at Phase B with full prose bodies.
 * Reads route param and looks up the matching section in references.generated.json.
 */

import { useParams } from 'react-router-dom';
import refs from '@/data/references.generated.json';
import { EmptyState } from '@/components/primitives/EmptyState';
import { Badge } from '@/components/primitives/Badge';
import { Button } from '@/components/primitives/Button';
import { Link } from 'react-router-dom';

interface RefSection {
  id: string;
  title: string;
  route: string;
  voice_register: 1 | 2 | 'mixed';
  source: string;
  status: 'placeholder' | 'authored';
}

export function ReferenceSection() {
  // Match by full pathname, since refs use route paths like /reference/indicators
  const path = window.location.pathname;
  const section = (refs as RefSection[]).find((s) => s.route === path);

  if (!section) {
    return (
      <EmptyState
        title="Reference section not found"
        body="That route didn't resolve to a known reference. Head back to the index."
        cta={
          <Link to="/reference">
            <Button variant="subtle">← Back to Reference</Button>
          </Link>
        }
      />
    );
  }

  return (
    <article className="px-6 py-10 max-w-prose mx-auto">
      <header className="mb-6">
        <div className="font-mono text-mono uppercase tracking-wider text-ink-faint">{section.id}</div>
        <h1 className="font-serif text-h1 font-semibold mt-1">{section.title}</h1>
        <div className="mt-2 flex items-center gap-2">
          <Badge tone="warn">placeholder</Badge>
          <span className="font-mono text-mono text-ink-faint">voice: {String(section.voice_register)}</span>
        </div>
      </header>
      <p className="font-serif text-body-prose text-ink-soft">
        Body authored in Phase B. The structure is locked — voice register {String(section.voice_register)},
        source-anchored to {section.source}.
      </p>
      <p className="mt-4 font-mono text-mono text-ink-faint">surface-id: {section.id}</p>
    </article>
  );
}

/**
 * Renders a single named-tool entry by URL param :toolId.
 */
import namedTools from '@/data/named-tools.generated.json';

interface NamedTool {
  id: string;
  name: string;
  what: string;
  where: string[];
  source: string;
}

export function NamedToolEntry() {
  const { toolId } = useParams<{ toolId: string }>();
  const tool = (namedTools as NamedTool[]).find((t) => t.id === toolId);
  if (!tool) {
    return (
      <EmptyState
        title="Named tool not found"
        body="Check the URL — IDs are like NT-FABS or NT-Stage-Gate-Tracker."
        cta={
          <Link to="/reference">
            <Button variant="subtle">← Back to Reference</Button>
          </Link>
        }
      />
    );
  }
  return (
    <article className="px-6 py-10 max-w-prose mx-auto">
      <header>
        <div className="font-mono text-mono uppercase tracking-wider text-ink-faint">{tool.id}</div>
        <h1 className="font-serif text-h1 font-semibold mt-1">{tool.name}</h1>
      </header>
      <section className="mt-6">
        <h2 className="font-mono text-mono uppercase tracking-wider text-ink-faint">What it is</h2>
        <p className="font-serif text-body-prose text-ink mt-1">{tool.what}</p>
      </section>
      <section className="mt-5">
