        </p>
      </header>
      <ul className="grid gap-3">
        {DRILLS.map((d) => (
          <li key={d.id}>
            <Link to={d.route} className="block focus-visible:outline focus-visible:outline-2 focus-visible:outline-accent rounded-3">
              <Card variant="surface" className="hover:border-[rgb(var(--accent)/0.30)] transition-colors duration-150">
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <div className="font-mono text-mono text-ink-faint">{d.id}</div>
                    <h3 className="font-serif text-h3 font-semibold mt-1">
                      {d.number} · {d.title}
                    </h3>
                    <p className="font-serif text-body-prose text-ink-soft mt-2">{d.blurb}</p>
                  </div>
                  {d.gates_simulator ? <Badge tone="accent">unlocks Simulator</Badge> : null}
