export function DrillShell() {
  const { drillId } = useParams<{ drillId: string }>();
  const drill = DRILLS.find((d) => d.number === drillId);
  if (!drill) {
    return <EmptyState title="Drill not found" body="Drill IDs are 3.1 through 3.9." surfaceId={`drill/${drillId ?? '?'}`} />;
