        title: 'Lesson 1.13 · Capstone',
        intro:
          'Ten calibration items. Sourced outside the canonical 20 and outside Module 3 drills, so this measures learning rather than recognition. Distractors author at Phase B.',
        items,
      }
    : {
        title: 'Hard Sentences · Capstone',
        intro:
          'Five cluster-sentence calibration items, sourced from variants not used in Module 5 practice. Distractors author at Phase E.',
        items,
      };
}

interface Props {
  module: 'M1' | 'M5';
}

export function Capstone({ module }: Props) {
  const { title, intro, items } = moduleFor(module);
  return (
    <article className="px-6 py-10 max-w-3xl mx-auto">
      <header className="mb-6">
        <div className="font-mono text-mono uppercase tracking-wider text-ink-faint">
          {module === 'M1' ? 'MC-LSN-1.13' : 'MC-HS-5.8'}
        </div>
        <h1 className="font-serif text-h1 font-semibold mt-1">{title}</h1>
        <p className="font-serif text-body-prose text-ink-soft mt-3">{intro}</p>
        <div className="mt-3 flex items-center gap-2">
          <Badge tone="warn">correct-only mode</Badge>
          <span className="font-mono text-mono text-ink-faint">
            {items.length} item{items.length === 1 ? '' : 's'}
          </span>
        </div>
      </header>
      <ol className="space-y-3">
        {items.map((item, i) => (
          <li key={item.id}>
            <Card variant="surface" data-calibration-id={item.id}>
              <div className="flex items-start justify-between gap-3">
                <div>
                  <div className="font-mono text-mono text-ink-faint">{item.id}</div>
                  <h3 className="font-serif text-h3 font-semibold mt-1">Item {i + 1}</h3>
                </div>
                <div className="flex items-center gap-2">
                  <Chip tone="accent">{item.trait_target}</Chip>
                  <Badge tone={item.stimulus_pending_ocr ? 'warn' : 'success'}>
                    {item.stimulus_pending_ocr ? 'OCR pending' : 'captured'}
                  </Badge>
                </div>
              </div>
              {item.stimulus ? (
                <p className="font-serif text-body-prose text-ink mt-3 leading-relaxed">{item.stimulus}</p>
              ) : (
                <p className="font-serif text-body-prose text-ink-faint mt-3 italic">
                  Stimulus pending OCR — wires in at Phase H.1 (DOCX extractor for{' '}
                  <code className="font-mono">{item.source_anchor.primary}</code>).
                </p>
              )}
              {item.main_conclusion ? (
                <p className="font-serif text-body-prose mt-3">
                  <span className="font-mono text-mono uppercase tracking-wider text-ink-faint">Correct conclusion · </span>
                  <span className="text-ink">{item.main_conclusion}</span>
                </p>
              ) : null}
              <p className="font-mono text-mono text-ink-faint mt-2">why: {item.trait_target_rationale}</p>
            </Card>
          </li>
        ))}
      </ol>
      {items.length === 0 ? <EmptyState title="No items" body="Calibration source missing." /> : null}
    </article>
  );
}

export function CapstoneRoute() {
  const path = window.location.pathname;
  const module: 'M1' | 'M5' = path.startsWith('/hard-sentences') ? 'M5' : 'M1';
  return <Capstone module={module} />;
}

