      { path: 'drills/:drillId', element: <Placeholder moduleId="MC-DRL" surfaceLabel="Drill" /> },

      // M4 Simulator — gated by Drill 3.4 (per §5)
      { path: 'simulator', element: <LockedRoute routeId="/simulator"><Placeholder moduleId="M4" surfaceLabel="Question Simulator + Trap Master" /></LockedRoute> },
      { path: 'simulator/bank', element: <LockedRoute routeId="/simulator/bank"><Placeholder moduleId="MC-SIM-4.2" surfaceLabel="20-Argument Classification Drill (canonical spine)" /></LockedRoute> },
      { path: 'simulator/trap-master', element: <LockedRoute routeId="/simulator/trap-master"><Placeholder moduleId="MC-SIM-4.3" surfaceLabel="Trap Master — 7 traits in depth" /></LockedRoute> },
      { path: 'simulator/trap-master/:traitId', element: <LockedRoute routeId="/simulator/trap-master"><Placeholder moduleId="MC-TRAIT" surfaceLabel="Trait deep-dive" /></LockedRoute> },
      { path: 'simulator/hard-mode', element: <LockedRoute routeId="/simulator/hard-mode"><Placeholder moduleId="MC-SIM-4.7" surfaceLabel="Hard Question Mastery layer" /></LockedRoute> },

