  { id: 'MC-DIA-6.4', title: 'R&R Review', route: '/diagnostics/rr-review', blurb: 'Recordings, transcripts, review prompts.' },
  { id: 'MC-DIA-6.5', title: 'Trait Diagnostic', route: '/diagnostics/trait-profile', blurb: 'Per-trait accuracy + which traps you fall for most.' },
