/**
 * Module 2 Reference sections — TS source with hand-authored bodies.
 * Phase B authored 2026-05-01 with voice locked from Lessons 1.1–1.12.
 *
 * Voice register 1 (decisive, verdict-style, procedural). No CAPS. No exclamation.
 * Each block carries kind: 'p' | 'h2' | 'callout' | 'list' | 'example' | 'table'.
 *
 * Reference sections are GENERATED by the pipeline (per JOSHUA DIRECTIVE scope split),
 * but their bodies are hand-authored here. The pipeline emits them with status='authored'
 * once a body lands.
 */

import type { ReferenceSectionT } from './schemas';

export const REFERENCE_SECTIONS: ReferenceSectionT[] = [
  // ── 2.A · Indicator Vault ─────────────────────────────────────────────────
  {
    id: 'MC-REF-2.A',
    title: 'The Indicator Vault',
    route: '/reference/indicators',
    voice_register: 1,
    source: 'Notes/Indicator word list .pdf (A) + Notes/main_conclusion_role_merged_note.pdf (S, table form) + Notes/Keyword.pdf (B)',
    status: 'authored',
    hook: 'Six categories. The whole reading job is faster once you can name the role of every signal word in front of you.',
    blocks: [
      {
        kind: 'p',
        text: 'The Indicator Vault is the lookup. The six color-coded categories above each carry one job: tell you what role the next clause will play. When the eye spots the word, the brain commits the role before you finish the sentence.',
      },
      {
        kind: 'callout',
        label: 'How to use it',
        body: 'Read once. Highlight the indicator. Predict the role of what follows. Confirm. Move on. Three seconds per indicator becomes one as the categories internalize.',
      },
      {
        kind: 'h2',
        text: 'Cross-reference',
      },
      {
        kind: 'list',
        items: [
          'FABS — the four premise indicators get their own page (2.C). They appear so often they earn the spotlight.',
          'Concession words (granted, although, while) get the Concession Decoder treatment (2.I). They look like agreement and are not.',
          'Pivot words (but, however, yet) flip a concession into the author’s real claim. The pivot is where the conclusion lands.',
        ],
      },
      {
        kind: 'p',
        text: 'Memorize the six. The drills (3.1, 3.2) repeat them until the categories become reflex.',
      },
    ],
  },

  // ── 2.B · 2-Part Conclusion Check ─────────────────────────────────────────
  {
    id: 'MC-REF-2.B',
    title: 'The 2-Part Conclusion Check',
    route: '/reference/2-part-check',
    voice_register: 1,
    source: 'Notes/Main conclusion (recap)_dup1.pdf (S) + Notes/Main Conclusion Synopsis.pdf (S)',
    status: 'authored',
    hook: 'The one tool that does not lie. Two questions. Both must be yes.',
    blocks: [
      {
        kind: 'h2',
        text: 'The check',
      },
      {
        kind: 'list',
        ordered: true,
        items: [
          'Does the sentence sound like the author’s opinion — a claim that someone could disagree with?',
          'Is the sentence supported by at least one other explicit claim in the stimulus?',
        ],
      },
      {
        kind: 'p',
        text: 'Both must be yes. If either is no, the candidate is not the main conclusion. A factual statement fails part one. An unsupported assertion fails part two. A claim the author concedes from someone else fails part one.',
      },
      {
        kind: 'callout',
        label: 'Why this works',
        body: 'A conclusion is, by definition, the load-bearing claim of the argument. It is held by the author and supported by something else in the text. Two conditions, no exceptions.',
      },
      {
        kind: 'example',
        label: 'Failure mode',
        body: 'Students often pick the most prominent statistic in the stimulus. A statistic is rarely the conclusion — it is almost always support. Run the 2-Part Check. If you can’t name what supports the statistic, it is not the conclusion.',
      },
      {
        kind: 'p',
        text: 'Apply this on every Main Conclusion question. After enough reps, the check runs in your head before you reach the answer choices.',
      },
