/**
 * Generic Reference section renderer.
 * Reads the section by current pathname from references.generated.json.
 * Bodies are authored in src/content/references.source.ts and emitted by the pipeline.
 */

import { useParams, Link } from 'react-router-dom';
import refs from '@/data/references.generated.json';
import namedTools from '@/data/named-tools.generated.json';
import { EmptyState } from '@/components/primitives/EmptyState';
import { Badge } from '@/components/primitives/Badge';
import { Button } from '@/components/primitives/Button';
import { Card } from '@/components/primitives/Card';

type Block =
  | { kind: 'p'; text: string }
  | { kind: 'h2'; text: string }
  | { kind: 'callout'; label: string; body: string }
  | { kind: 'list'; ordered?: boolean; items: string[] }
  | { kind: 'example'; label: string; body: string }
  | { kind: 'table'; columns: string[]; rows: string[][] };

interface RefSection {
  id: string;
  title: string;
  route: string;
  voice_register: 1 | 2 | 'mixed';
  source: string;
  status: 'placeholder' | 'authored';
  hook?: string;
  blocks?: Block[];
}

function RenderBlock({ block }: { block: Block }) {
  switch (block.kind) {
    case 'p':
      return <p className="font-serif text-body-prose text-ink leading-relaxed">{block.text}</p>;
    case 'h2':
      return <h2 className="font-serif text-h2 font-semibold mt-6">{block.text}</h2>;
    case 'callout':
      return (
        <Card variant="elev" className="border-l-4 border-l-[rgb(var(--accent)/0.50)]">
          <div className="font-mono text-mono uppercase tracking-wider text-accent">{block.label}</div>
          <p className="font-serif text-body-prose text-ink mt-2">{block.body}</p>
        </Card>
      );
    case 'list':
      if (block.ordered) {
        return (
          <ol className="font-serif text-body-prose text-ink list-decimal pl-5 space-y-1.5 marker:text-ink-faint">
            {block.items.map((it, i) => (
              <li key={i}>{it}</li>
            ))}
          </ol>
        );
      }
      return (
        <ul className="font-serif text-body-prose text-ink list-disc pl-5 space-y-1.5 marker:text-ink-faint">
          {block.items.map((it, i) => (
            <li key={i}>{it}</li>
          ))}
        </ul>
      );
    case 'example':
      return (
        <Card variant="surface" className="border-l-4 border-l-[rgb(var(--role-premise)/0.50)]">
          <div className="font-mono text-mono uppercase tracking-wider text-[rgb(var(--role-premise))]">
            Example · {block.label}
          </div>
          <p className="font-serif text-body-prose text-ink mt-2">{block.body}</p>
        </Card>
      );
    case 'table':
      return (
        <div className="overflow-x-auto rounded-3 border border-[rgb(var(--border)/0.10)]">
          <table className="w-full text-left">
            <thead className="bg-[rgb(var(--surface-elev))]">
              <tr>
                {block.columns.map((c) => (
                  <th key={c} className="px-3 py-2 font-mono text-mono uppercase tracking-wider text-ink-faint">
                    {c}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {block.rows.map((r, i) => (
                <tr key={i} className="border-t border-[rgb(var(--border)/0.06)]">
                  {r.map((cell, j) => (
                    <td key={j} className="px-3 py-2 font-serif text-body text-ink">
                      {cell}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
  }
}

export function ReferenceSection() {
  const path = window.location.pathname;
  const section = (refs as RefSection[]).find((s) => s.route === path);

  if (!section) {
    return (
      <EmptyState
        title="Reference section not found"
        body="That route didn't resolve to a known reference. Head back to the index."
        cta={
          <Link to="/reference">
            <Button variant="subtle">← Back to Reference</Button>
          </Link>
        }
      />
    );
  }

  return (
    <article className="px-6 py-10 max-w-prose mx-auto">
      <header className="mb-6">
        <div className="font-mono text-mono uppercase tracking-wider text-ink-faint">{section.id}</div>
        <h1 className="font-serif text-h1 font-semibold mt-1">{section.title}</h1>
        <div className="mt-2 flex items-center gap-2">
          <Badge tone={section.status === 'authored' ? 'success' : 'warn'}>{section.status}</Badge>
          <span className="font-mono text-mono text-ink-faint">voice: {String(section.voice_register)}</span>
        </div>
        {section.hook ? (
          <p className="font-serif text-body-prose text-ink-soft italic mt-4 border-l-2 border-l-[rgb(var(--accent)/0.40)] pl-3">
            {section.hook}
          </p>
        ) : null}
      </header>
      {section.blocks && section.blocks.length > 0 ? (
        <div className="space-y-4">
          {section.blocks.map((b, i) => (
            <RenderBlock key={i} block={b} />
          ))}
        </div>
      ) : (
        <p className="font-serif text-body-prose text-ink-soft">
          Body authored in Phase B. Source-anchored to {section.source}.
        </p>
      )}
      <p className="mt-8 font-mono text-mono text-ink-faint border-t border-[rgb(var(--border)/0.08)] pt-4">
        source: {section.source}
      </p>
    </article>
  );
}

interface NamedTool {
  id: string;
  name: string;
  what: string;
  where: string[];
  source: string;
}

export function NamedToolEntry() {
  const { toolId } = useParams<{ toolId: string }>();
  const tool = (namedTools as NamedTool[]).find((t) => t.id === toolId);
  if (!tool) {
    return (
      <EmptyState
        title="Named tool not found"
        body="Check the URL — IDs are like NT-FABS or NT-Stage-Gate-Tracker."
        cta={
          <Link to="/reference">
            <Button variant="subtle">← Back to Reference</Button>
          </Link>
        }
      />
    );
  }
  return (
    <article className="px-6 py-10 max-w-prose mx-auto">
      <header>
        <div className="font-mono text-mono uppercase tracking-wider text-ink-faint">{tool.id}</div>
        <h1 className="font-serif text-h1 font-semibold mt-1">{tool.name}</h1>
      </header>
      <section className="mt-6">
        <h2 className="font-mono text-mono uppercase tracking-wider text-ink-faint">What it is</h2>
        <p className="font-serif text-body-prose text-ink mt-1">{tool.what}</p>
      </section>
      <section className="mt-5">
        <h2 className="font-mono text-mono uppercase tracking-wider text-ink-faint">Where it appears</h2>
        <ul className="mt-1 space-y-1">
          {tool.where.map((w) => (
            <li key={w} className="font-mono text-mono text-ink-soft">
              {w}
            </li>
          ))}
        </ul>
      </section>
      <p className="mt-6 font-mono text-mono text-ink-faint">source: {tool.source}</p>
    </article>
  );
}

