 *
 * This file is hand-authored. Pipeline parity-verifies it like lessons + calibration
 * (per JOSHUA DIRECTIVE 2026-04-30 scope split).
 */

// ── Common types ─────────────────────────────────────────────────────────────
export type Letter = 'A' | 'B' | 'C' | 'D' | 'E';

export interface IndicatorIdQuestion {
