/**
 * Drill 3.1 · Indicator Word ID — Stage-Gate frame.
 * Stage 1 carries 5 authored items. Stages 2-4 stub pending Joshua's authoring pass.
 */

import { StageGateTracker, type Stage } from '@/components/stage-gate/StageGateTracker';
import { Card } from '@/components/primitives/Card';
import { Button } from '@/components/primitives/Button';
import { Chip } from '@/components/primitives/Chip';
import { DRILL_3_1_STAGE_1, type IndicatorIdQuestion } from '@/content/drills.source';
import { useUser } from '@/hooks/useUser';
import { useModuleProgress } from '@/hooks/useModuleProgress';

const stages: Stage<IndicatorIdQuestion>[] = [
  {
    number: 1,
    title: 'Single-word identification',
    hint: 'Read the sentence. Tap the category for the highlighted word.',
    questions: DRILL_3_1_STAGE_1.map((q) => ({ id: q.id, prompt: q.prompt, payload: q })),
  },
  { number: 2, title: 'Multi-word phrases', hint: 'Stage 2 content authors at C.10.', questions: [] },
  { number: 3, title: 'Mixed signals', hint: 'Stage 3 content authors at C.10.', questions: [] },
  { number: 4, title: 'Speed run', hint: 'Stage 4 content authors at C.10.', questions: [] },
];

const TONE_BY_CAT: Record<string, 'conclusion' | 'premise' | 'pivot' | 'opposing' | 'concession' | 'background' | 'accent'> = {
  conclusion: 'conclusion',
  premise: 'premise',
  pivot: 'pivot',
  concession: 'concession',
  opposing: 'opposing',
  opinion: 'accent',
};

export function Drill3_1() {
  const { user } = useUser();
  const { markDrillComplete } = useModuleProgress(user?.id);

  return (
    <article className="px-6 py-10 max-w-3xl mx-auto">
      <StageGateTracker
        drillId="MC-DRL-3.1"
        stages={stages}
        renderQuestion={(q, onAnswer, state) => (
          <IndicatorQuestionView q={q.payload} state={state} onAnswer={onAnswer} />
        )}
        onDrillComplete={() => markDrillComplete?.('MC-DRL-3.1')}
      />
    </article>
  );
}

interface ViewProps {
  q: IndicatorIdQuestion;
  state: { answered: boolean; correct: boolean | null };
  onAnswer: (correct: boolean) => void;
}

function IndicatorQuestionView({ q, state, onAnswer }: ViewProps) {
  function pick(category: IndicatorIdQuestion['correct_category']) {
    if (state.answered) return;
    onAnswer(category === q.correct_category);
  }
  const highlighted = q.text.replace(
    q.highlighted_word,
    `__HIGHLIGHT__${q.highlighted_word}__/HIGHLIGHT__`,
  );
  const parts = highlighted.split(/__HIGHLIGHT__|__\/HIGHLIGHT__/);

  return (
    <Card variant="surface">
      <p className="font-mono text-mono uppercase tracking-wider text-ink-faint">{q.id}</p>
      <p className="font-serif text-body-prose text-ink mt-2 leading-relaxed">
        {parts.map((p, i) =>
          i % 2 === 1 ? (
            <mark key={i} className="bg-[rgb(var(--accent)/0.20)] text-accent rounded px-1 py-0.5 not-italic">
              {p}
            </mark>
          ) : (
            <span key={i}>{p}</span>
          ),
        )}
      </p>
      <p className="font-serif text-body text-ink-soft italic mt-3">{q.prompt}</p>
      <div className="mt-3 flex flex-wrap gap-2">
        {q.category_options.map((cat) => (
          <Button
            key={cat}
            variant="subtle"
            size="sm"
            disabled={state.answered}
            onClick={() => pick(cat)}
          >
            <Chip tone={TONE_BY_CAT[cat]}>{cat}</Chip>
          </Button>
        ))}
      </div>
      {state.answered ? (
        <p
          className={`mt-3 font-serif text-body-prose ${
            state.correct ? 'text-[rgb(var(--success))]' : 'text-[rgb(var(--error))]'
          }`}
        >
          {state.correct ? '✓ ' : '✗ '}
          {q.rationale}
        </p>
      ) : null}
    </Card>
  );
}

