1	/**
2	 * Module progress hook — backs the LockedRoute / unlock cascade per §5.
3	 */
4	
5	import { useCallback, useEffect, useState } from 'react';
6	import { getPersistence } from '@/persistence/factory';
7	import { TABLES, ModuleProgress } from '@/persistence/records';
8	import { now } from '@/lib/ids';
9	import { INITIAL_UNLOCKED_ROUTES, unlockNext, type ProgressShape } from '@/lib/ordering';
10	import { STUB_USER_ID_EXPORT } from './useUser';
11	
12	const PROGRESS_ID = '00000000-0000-4000-8000-000000000010';
13	
14	export function useModuleProgress(): {
15	  progress: ModuleProgress | null;
16	  markRouteVisited: (routeId: string) => Promise<void>;
17	  markLessonComplete: (lessonId: string, routeId: string) => Promise<void>;
18	} {
19	  const [progress, setProgress] = useState<ModuleProgress | null>(null);
20	
21	  useEffect(() => {
22	    let cancelled = false;
23	    (async () => {
24	      const persist = getPersistence(STUB_USER_ID_EXPORT);
25	      let existing = await persist.get<ModuleProgress>(TABLES.module_progress, PROGRESS_ID);
26	      if (!existing) {
27	        existing = ModuleProgress.parse({
28	          id: PROGRESS_ID,
29	          user_id: STUB_USER_ID_EXPORT,
30	          unlocked_modules: ['M1', 'M2', 'M3', 'M5', 'M6'],
31	          unlocked_routes: INITIAL_UNLOCKED_ROUTES,
32	          completed_lessons: [],
33	          completed_drills: [],
34	          completed_capstones: [],
35	          updated_at: now(),
36	        });
37	        await persist.set(TABLES.module_progress, PROGRESS_ID, existing);
38	      }
39	      if (!cancelled) setProgress(existing);
40	    })();
41	    return () => {
42	      cancelled = true;
43	    };
44	  }, []);
45	
46	  const markRouteVisited = useCallback(async (_routeId: string) => {
47	    // Reserved for analytics in Module 6.
48	  }, []);
49	
50	  const markLessonComplete = useCallback(
51	    async (lessonId: string, routeId: string) => {
52	      const persist = getPersistence(STUB_USER_ID_EXPORT);
53	      const current = await persist.get<ModuleProgress>(TABLES.module_progress, PROGRESS_ID);
