1	/**
2	 * Drill 3.6 · Design the Conclusion — whimsical premise pair → student writes a valid + invalid conclusion.
3	 *
4	 * Evaluator pipeline (architecture-plan §7):
5	 *   Step 1 — premise-keyword overlap (cheap, deterministic)
6	 *   Step 2 — meaning similarity (transformers.js MiniLM, lazy-loaded only on this route)
7	 *
8	 * v1 ships with the keyword-overlap step always-on. The MiniLM step is opt-in via the
9	 * "Run semantic check" button — keeps the bundle lean and the model load deferred.
10	 */
11	
12	import { useState } from 'react';
13	import { Card } from '@/components/primitives/Card';
14	import { Textarea } from '@/components/primitives/Input';
15	import { Button } from '@/components/primitives/Button';
16	import { Badge } from '@/components/primitives/Badge';
17	import { Chip } from '@/components/primitives/Chip';
18	import { DRILL_3_6_QUESTIONS, type DesignConclusionQuestion } from '@/content/drills.source';
19	import { useUser } from '@/hooks/useUser';
20	import { useModuleProgress } from '@/hooks/useModuleProgress';
21	import { evaluateDesignedConclusion, type Classification } from '@/lib/ai-templates/whimsical-evaluator';
22	
23	export function Drill3_6() {
24	  const user = useUser();
25	  const { markDrillComplete } = useModuleProgress(user?.id);
26	  const [qIndex, setQIndex] = useState(0);
27	
28	  const q = DRILL_3_6_QUESTIONS[qIndex]!;
29	  const isLast = qIndex + 1 >= DRILL_3_6_QUESTIONS.length;
30	
31	  function next() {
32	    if (isLast) {
33	      markDrillComplete?.('MC-DRL-3.6');
34	    } else {
35	      setQIndex(qIndex + 1);
36	    }
37	  }
38	
39	  return (
40	    <article className="px-6 py-10 max-w-3xl mx-auto space-y-5">
41	      <header>
42	        <div className="font-mono text-mono uppercase tracking-wider text-ink-faint">MC-DRL-3.6</div>
43	        <h1 className="font-serif text-h1 font-semibold mt-1">Design the Conclusion</h1>
44	        <p className="font-serif text-body-prose text-ink-soft mt-2">
45	          A premise pair from the dragon-and-broom universe. Write one valid conclusion and one
46	          invalid-but-tempting one. Stay inside the universe — the evaluator catches outside-knowledge imports.
47	        </p>
48	      </header>
49	
50	      <Card variant="elev">
51	        <p className="font-mono text-mono text-ink-faint">
52	          Question {qIndex + 1} of {DRILL_3_6_QUESTIONS.length} · {q.id}
53	        </p>
54	        <div className="mt-3 space-y-1">
55	          <p className="font-serif text-body-prose text-ink">
56	            <span className="font-mono text-mono uppercase tracking-wider text-[rgb(var(--role-premise))] mr-2">P1</span>
57	            {q.premise_pair.p1}
58	          </p>
59	          <p className="font-serif text-body-prose text-ink">
60	            <span className="font-mono text-mono uppercase tracking-wider text-[rgb(var(--role-premise))] mr-2">P2</span>
61	            {q.premise_pair.p2}
62	          </p>
63	        </div>
64	      </Card>
65	
66	      <ConclusionInputs q={q} onSubmit={next} isLast={isLast} />
67	    </article>
68	  );
69	}
70	
71	function ConclusionInputs({ q, onSubmit, isLast }: { q: DesignConclusionQuestion; onSubmit: () => void; isLast: boolean }) {
72	  const [validInput, setValidInput] = useState('');
73	  const [invalidInput, setInvalidInput] = useState('');
74	  const [validClass, setValidClass] = useState<Classification | null>(null);
75	  const [invalidClass, setInvalidClass] = useState<Classification | null>(null);
76	  const [running, setRunning] = useState(false);
77	
78	  async function evaluate() {
79	    setRunning(true);
80	    const a = evaluateDesignedConclusion({
81	      premise_pair: q.premise_pair,
82	      student_text: validInput,
83	      valid_model: q.valid_model,
84	      invalid_model: q.invalid_model,
85	    });
86	    const b = evaluateDesignedConclusion({
87	      premise_pair: q.premise_pair,
88	      student_text: invalidInput,
89	      valid_model: q.valid_model,
90	      invalid_model: q.invalid_model,
91	    });
92	    setValidClass(a.classification);
93	    setInvalidClass(b.classification);
94	    setRunning(false);
95	  }
96	
97	  function diagnostic(c: Classification | null): string {
98	    if (!c) return '';
99	    if (c === 'Valid') return q.diagnostic_messages.valid_match;
100	    if (c === 'Invalid but interesting') return q.diagnostic_messages.invalid_but_interesting;
101	    return q.diagnostic_messages.misses_the_premises;
102	  }
103	
104	  function tone(c: Classification | null): 'success' | 'warn' | 'error' | 'neutral' {
105	    if (c === 'Valid') return 'success';
106	    if (c === 'Invalid but interesting') return 'warn';
107	    if (c === 'Misses the premises entirely') return 'error';
108	    return 'neutral';
109	  }
110	
111	  return (
112	    <div className="space-y-4">
113	      <Card variant="surface">
114	        <label className="font-mono text-mono uppercase tracking-wider text-[rgb(var(--success))]">
115	          Your VALID conclusion
116	        </label>
117	        <Textarea
118	          value={validInput}
119	          onChange={(e) => setValidInput(e.target.value)}
120	          placeholder="Apply the premises faithfully…"
121	          className="mt-2"
122	        />
123	        {validClass ? (
124	          <div className="mt-3">
125	            <Badge tone={tone(validClass)}>{validClass}</Badge>
126	            <p className="font-serif text-body text-ink mt-2">{diagnostic(validClass)}</p>
127	          </div>
128	        ) : null}
129	      </Card>
130	
131	      <Card variant="surface">
132	        <label className="font-mono text-mono uppercase tracking-wider text-[rgb(var(--warn))]">
133	          Your INVALID conclusion
134	        </label>
135	        <Textarea
136	          value={invalidInput}
137	          onChange={(e) => setInvalidInput(e.target.value)}
138	          placeholder="Construct a tempting-but-wrong move (reverse the conditional, etc.)…"
139	          className="mt-2"
140	        />
141	        {invalidClass ? (
142	          <div className="mt-3">
143	            <Badge tone={tone(invalidClass)}>{invalidClass}</Badge>
144	            <p className="font-serif text-body text-ink mt-2">{diagnostic(invalidClass)}</p>
145	          </div>
146	        ) : null}
147	      </Card>
148	
149	      <div className="flex items-center gap-3">
150	        <Button disabled={!validInput || !invalidInput || running} onClick={evaluate}>
151	          {running ? 'Evaluating…' : 'Evaluate'}
152	        </Button>
153	        <Chip tone="neutral">offline · keyword-overlap pipeline</Chip>
154	        {validClass && invalidClass ? (
155	          <Button variant="primary" onClick={onSubmit} className="ml-auto">
156	            {isLast ? 'Finish drill' : 'Next →'}
157	          </Button>
158	        ) : null}
159	      </div>
160	    </div>
161	  );
162	}

