58	function ChainMappingExercise({ q, onComplete }: { q: ChainMappingQuestion; onComplete: () => void }) {
59	  // Split stimulus into sentences and let student tag each.
60	  const sentences = q.stimulus.split(/(?<=[.!?])\s+/).filter(Boolean);
61	  const [assignments, setAssignments] = useState<Assignments>(() => Object.fromEntries(sentences.map((_, i) => [i, null])));
62	  const [submitted, setSubmitted] = useState(false);
63	
64	  function setRole(i: number, role: Role) {
65	    setAssignments((a) => ({ ...a, [i]: role }));
66	  }
67	
68	  function correctRole(sentence: string): Role | null {
69	    const s = sentence.trim().replace(/[.!?]+$/, '').toLowerCase();
70	    if (s.includes(q.layers.main_conclusion.toLowerCase().replace(/[.!?]+$/, ''))) return 'main';
71	    if (q.layers.intermediate_conclusion && s.includes(q.layers.intermediate_conclusion.toLowerCase().replace(/[.!?]+$/, ''))) return 'intermediate';
72	    if (q.layers.premises.some((p) => s.includes(p.toLowerCase().replace(/[.!?]+$/, '')))) return 'premise';
73	    return null;
74	  }
75	
76	  const allTagged = sentences.every((_, i) => assignments[i] !== null);
77	  const correctCount = submitted ? sentences.filter((sent, i) => assignments[i] === correctRole(sent)).length : 0;
78	
79	  return (
80	    <Card variant="elev" className="space-y-3">
81	      <p className="font-mono text-mono uppercase tracking-wider text-ink-faint">Tag each sentence</p>
82	      <ul className="space-y-2">
83	        {sentences.map((s, i) => {
84	          const cur = assignments[i];
85	          const correct = submitted ? correctRole(s) : null;
86	          const right = submitted && cur === correct;
87	          return (
88	            <li key={i}>
89	              <div
90	                className={`rounded-3 border p-3 ${
91	                  submitted
92	                    ? right
93	                      ? 'border-[rgb(var(--success)/0.40)] bg-[rgb(var(--success)/0.06)]'
94	                      : 'border-[rgb(var(--error)/0.40)] bg-[rgb(var(--error)/0.06)]'
95	                    : 'border-[rgb(var(--border)/0.10)]'
96	                }`}
97	              >
98	                <p className="font-serif text-body-prose text-ink">{s}</p>
99	                <div className="mt-2 flex flex-wrap gap-1.5">
100	                  {(['main', 'intermediate', 'premise'] as Role[]).map((r) => (
101	                    <Button
102	                      key={r}
103	                      variant={cur === r ? 'primary' : 'subtle'}
104	                      size="sm"
105	                      disabled={submitted}
106	                      onClick={() => setRole(i, r)}
107	                    >
108	                      {r}
109	                    </Button>
110	                  ))}
111	                </div>
112	                {submitted && !right ? (
113	                  <p className="mt-2 font-mono text-mono text-ink-faint">
114	                    correct: <Chip tone="accent">{correct ?? 'n/a'}</Chip>
115	                  </p>
116	                ) : null}
117	              </div>
118	            </li>
119	          );
120	        })}
121	      </ul>
122	      {!submitted ? (
123	        <div className="flex justify-end">
124	          <Button disabled={!allTagged} onClick={() => setSubmitted(true)}>
125	            Submit
126	          </Button>
127	        </div>
128	      ) : (
129	        <div className="flex items-center justify-between">
130	          <p className="font-serif text-body-prose text-ink">
131	            {correctCount} / {sentences.length} correct
132	          </p>
133	          <Button onClick={onComplete}>Next →</Button>
134	        </div>
135	      )}
136	    </Card>
137	  );
138	}

