        {HARD_SECTIONS.map((s) => (
          <li key={s.id}>
            <Link to={s.route} className="block">
              <Card variant="surface" className="hover:border-[rgb(var(--accent)/0.30)] transition-colors">
                <div className="font-mono text-mono text-ink-faint">{s.id}</div>
                <h3 className="font-serif text-h3 font-semibold mt-1">
                  {s.number} · {s.title}
                </h3>
              </Card>
            </Link>
          </li>
        ))}
      </ul>
    </article>
  );
}

export function HardSentenceSection() {
  const { sectionId } = useParams<{ sectionId: string }>();
  const sec = HARD_SECTIONS.find((s) => s.number === sectionId);
  if (!sec) {
    return <EmptyState title="Hard Sentences section not found" surfaceId={`hard/${sectionId ?? '?'}`} />;
  }
  return (
    <EmptyState
      title={`${sec.number} · ${sec.title}`}
      body="Body authored at Phase E."
      surfaceId={sec.id}
    />
  );
}

