input.content:
/**
 * MC-LSN-1.13 + MC-HS-5.8 Capstones.
 * M5.8 ships at Phase E with 5 fully authored cluster-decomposition MCQ items
 *   (src/content/m5-capstone.source.ts).
 * M1.13 ships at Phase A.8 in correct-only mode; full 60 distractors author at Phase B/D.
 */

import { useState } from 'react';
import calibration from '@/data/calibration.generated.json';
import { Card } from '@/components/primitives/Card';
import { Badge } from '@/components/primitives/Badge';
import { Chip } from '@/components/primitives/Chip';
import { Button } from '@/components/primitives/Button';
import { EmptyState } from '@/components/primitives/EmptyState';
import { M5_CAPSTONE, type CapstoneItem, type CapstoneChoice } from '@/content/m5-capstone.source';
import { useUser } from '@/hooks/useUser';
import { getPersistence } from '@/persistence/factory';
import { TABLES } from '@/persistence/records';
import { newId, now } from '@/lib/ids';

interface CalibrationFile {
  $comment?: string;
  $schema?: string;
  generated_at?: string;
  generator?: string;
  items: Array<CalibrationItemMeta>;
}
interface CalibrationItemMeta {
  id: string;
  calibration_only: true;
  calibration_module: 'M1' | 'M5';
  trait_target: string;
  trait_target_rationale: string;
  structure_family?: string;
  stimulus_pending_ocr?: boolean;
  stimulus?: string;
  main_conclusion?: string;
  source_anchor: { primary: string; answer_key?: string; audit_tier?: string };
}

interface Props {
  module: 'M1' | 'M5';
}

export function Capstone({ module }: Props) {
  if (module === 'M5') return <M5CapstoneView />;
  return <M1CapstoneCorrectOnly />;
}

export function CapstoneRoute() {
  const path = window.location.pathname;
  const module: 'M1' | 'M5' = path.startsWith('/hard-sentences') ? 'M5' : 'M1';
  return <Capstone module={module} />;
}

// ─── M1.13 (correct-only mode) ─────────────────────────────────────────────
function M1CapstoneCorrectOnly() {
  const cf = calibration as CalibrationFile;
  const items = cf.items.filter((i) => i.calibration_module === 'M1');
  return (
    <article className="px-6 py-10 max-w-3xl mx-auto">
      <header className="mb-6">
        <div className="font-mono text-mono uppercase tracking-wider text-ink-faint">MC-LSN-1.13</div>
        <h1 className="font-serif text-h1 font-semibold mt-1">Lesson 1.13 · Capstone</h1>
        <p className="font-serif text-body-prose text-ink-soft mt-3">
          Ten calibration items. Sourced outside the canonical 20 and outside Module 3 drills, so this
          measures learning rather than recognition. Distractors author at Phase B/D.
        </p>
        <div className="mt-3 flex items-center gap-2">
          <Badge tone="warn">correct-only mode</Badge>
          <span className="font-mono text-mono text-ink-faint">{items.length} items</span>
        </div>
      </header>
      <ol className="space-y-3">
        {items.map((item, i) => (
          <li key={item.id}>
            <Card variant="surface" data-calibration-id={item.id}>
              <div className="flex items-start justify-between gap-3">
                <div>
                  <div className="font-mono text-mono text-ink-faint">{item.id}</div>
                  <h3 className="font-serif text-h3 font-semibold mt-1">Item {i + 1}</h3>
                </div>
                <div className="flex items-center gap-2">
                  <Chip tone="accent">{item.trait_target}</Chip>
                  <Badge tone={item.stimulus_pending_ocr ? 'warn' : 'success'}>
                    {item.stimulus_pending_ocr ? 'OCR pending' : 'captured'}
                  </Badge>
                </div>
              </div>
              {item.stimulus ? (
                <p className="font-serif text-body-prose text-ink mt-3 leading-relaxed">{item.stimulus}</p>
              ) : (
                <p className="font-serif text-body-prose text-ink-faint mt-3 italic">
                  Stimulus pending OCR — wires in at Phase H.1 (DOCX extractor for{' '}
                  <code className="font-mono">{item.source_anchor.primary}</code>).
                </p>
              )}
              {item.main_conclusion ? (
                <p className="font-serif text-body-prose mt-3">
                  <span className="font-mono text-mono uppercase tracking-wider text-ink-faint">Correct conclusion · </span>
                  <span className="text-ink">{item.main_conclusion}</span>
                </p>
              ) : null}
              <p className="font-mono text-mono text-ink-faint mt-2">why: {item.trait_target_rationale}</p>
            </Card>
          </li>
        ))}
      </ol>
      {items.length === 0 ? <EmptyState title="No items" body="Calibration source missing." /> : null}
    </article>
  );
}

// ─── M5.8 (full MCQ mode with 5 items, 4 choices each) ─────────────────────
function M5CapstoneView() {
  const user = useUser();
  const [index, setIndex] = useState(0);
  const [picks, setPicks] = useState<Record<string, string>>({});
  const [completed, setCompleted] = useState(false);
  const item = M5_CAPSTONE[index]!;
  const isLast = index >= M5_CAPSTONE.length - 1;

  async function record(choice: CapstoneChoice) {
    setPicks((p) => ({ ...p, [item.id]: choice.letter }));
    if (!user) return;
    const persist = getPersistence(user.id);
    await persist.set(TABLES.calibration_attempts, newId(), {
      id: newId(),
      user_id: user.id,
