          <ol className="mt-3 space-y-2">
            {M5_CAPSTONE.map((q) => {
              const picked = q.choices.find((c) => c.letter === picks[q.id]);
              return (
                <li key={q.id} className="font-serif text-body text-ink">
                  <span className="font-mono text-mono text-ink-faint">{q.id}</span> · picked {picked?.letter ?? '—'} ·{' '}
                  <span className={picked?.is_correct ? 'text-[rgb(var(--success))]' : 'text-[rgb(var(--error))]'}>
                    {picked?.is_correct ? '✓' : '✗'}
                  </span>
                </li>
              );
            })}
          </ol>
        </Card>
      </article>
    );
  }

  return (
    <article className="px-6 py-10 max-w-3xl mx-auto space-y-4">
      <header>
