  const due = new Date(now.getTime() + interval_days * 24 * 60 * 60 * 1000);

  return {
    ease,
    interval_days,
    lapses,
    reps,
    due_at_iso: due.toISOString(),
    last_grade: q,
  };
}

export function isDue(state: SrsState, now: Date = new Date()): boolean {
  return new Date(state.due_at_iso).getTime() <= now.getTime();
}

