                  <div>
                    <div className="font-mono text-mono text-ink-faint">{r.kind}</div>
                    <h3 className="font-serif text-h3 font-semibold mt-1">{r.title}</h3>
                    <p className="font-serif text-body text-ink-soft mt-2">{r.reason}</p>
                  </div>
                  <Badge tone={r.priority === 1 ? 'accent' : 'neutral'}>P{r.priority}</Badge>
                </div>
                <Link to={r.href} className="inline-block mt-3">
                  <Button size="sm">Go →</Button>
                </Link>
              </Card>
            </li>
          ))}
        </ul>
      )}
    </article>
  );
}

