/**
 * MC-DIA-6.7 · SRS Queue.
 * SM-2 algorithm. Reviews missed simulator questions and flagged drill items.
 */

import { useState } from 'react';
import { useDiagnostics } from '@/hooks/useDiagnostics';
import { review, isDue, type SrsState } from '@/lib/srs';
import { getPersistence } from '@/persistence/factory';
import { TABLES, type SrsQueueItem } from '@/persistence/records';
import { useUser } from '@/hooks/useUser';
import { now } from '@/lib/ids';
import { Card } from '@/components/primitives/Card';
import { Button } from '@/components/primitives/Button';
import { Badge } from '@/components/primitives/Badge';
import { Chip } from '@/components/primitives/Chip';
import { EmptyState } from '@/components/primitives/EmptyState';
import { LoadingSkeleton } from '@/components/primitives/LoadingSkeleton';

export function SrsQueue() {
  const d = useDiagnostics();
  const user = useUser();
  const [reviewedIds, setReviewedIds] = useState<Set<string>>(new Set());

  if (d.loading) {
    return (
      <div className="px-6 py-10 max-w-3xl mx-auto">
        <LoadingSkeleton lines={6} />
      </div>
    );
  }

  const dueItems = d.srsItems.filter((s) => {
    if (reviewedIds.has(s.id)) return false;
    return isDue(toState(s));
  });
  const upcoming = d.srsItems.filter((s) => !isDue(toState(s)));

  async function grade(item: SrsQueueItem, q: number) {
    if (!user) return;
    const next = review(toState(item), q);
    const merged: SrsQueueItem = {
      ...item,
      ease: next.ease,
      interval_days: next.interval_days,
      lapses: next.lapses,
      due_at: next.due_at_iso,
      last_grade: next.last_grade,
      last_reviewed_at: now(),
    };
    const persist = getPersistence(user.id);
    await persist.set(TABLES.srs_queue, item.id, merged);
    setReviewedIds((s) => new Set(s).add(item.id));
  }

  return (
    <article className="px-6 py-10 max-w-3xl mx-auto space-y-5">
      <header>
        <div className="font-mono text-mono uppercase tracking-wider text-ink-faint">MC-DIA-6.7</div>
        <h1 className="font-serif text-h1 font-semibold mt-1">SRS Queue</h1>
        <p className="font-serif text-body-prose text-ink-soft mt-2">
          Spaced-repetition queue (SM-2). Grade your recall on each item; the algorithm schedules the
          next review.
        </p>
        <div className="mt-3 flex gap-2">
          <Badge tone="accent">{dueItems.length} due</Badge>
          <Badge tone="neutral">{upcoming.length} upcoming</Badge>
        </div>
      </header>

      {d.srsItems.length === 0 ? (
        <EmptyState
          title="Queue is empty"
          body="Items add to the queue as you miss questions in the Simulator and capstones."
          surfaceId="MC-DIA-6.7"
        />
      ) : null}

      {dueItems.length > 0 ? (
        <section>
          <h2 className="font-mono text-mono uppercase tracking-wider text-ink-faint">Due now</h2>
          <ul className="mt-3 space-y-3">
            {dueItems.map((item) => (
              <li key={item.id}>
                <Card variant="surface">
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <div className="font-mono text-mono text-ink-faint">{item.surface_id}</div>
                      <p className="font-serif text-body text-ink mt-1">
                        ease {item.ease.toFixed(2)} · interval {item.interval_days}d · lapses {item.lapses}
                      </p>
                    </div>
                    <Chip tone="accent">due</Chip>
                  </div>
                  <div className="mt-3 flex flex-wrap gap-1.5">
                    {([0, 1, 2, 3, 4, 5] as const).map((q) => (
