import { createBrowserRouter, Navigate } from 'react-router-dom';
import { WorkspaceShell } from '@/components/workspace-shell/WorkspaceShell';
import { LockedRoute } from '@/components/workspace-shell/LockedRoute';
import { ModuleIndex } from '@/modules/ModuleIndex';
import { LessonsIndex } from '@/modules/lessons/LessonsIndex';
import { Lesson } from '@/modules/lessons/Lesson';
import { CapstoneRoute } from '@/modules/lessons/Capstone';
import { Placeholder } from '@/modules/Placeholder';
import { ReferenceIndex } from '@/modules/reference/ReferenceIndex';
import { ReferenceSection, NamedToolEntry } from '@/modules/reference/ReferenceSection';
import { IndicatorVault } from '@/modules/reference/IndicatorVault';
import { DrillsIndex, DrillShell } from '@/modules/drills/DrillsIndex';
import {
  SimulatorOverview,
  QuestionBank,
  TrapMaster,
  HardMode,
} from '@/modules/simulator/SimulatorShell';
import { TraitDeepDive } from '@/components/trap-master/TraitDeepDive';
import { HardSentencesIndex, HardSentenceSection } from '@/modules/hard-sentences/HardSentencesIndex';
import { DiagnosticsIndex } from '@/modules/diagnostics/DiagnosticsIndex';
import { Philosophy } from '@/modules/diagnostics/Philosophy';
import { Dashboard } from '@/modules/diagnostics/Dashboard';
import { Recommendations } from '@/modules/diagnostics/Recommendations';
import { RrReview } from '@/modules/diagnostics/RrReview';
import { TraitProfile } from '@/modules/diagnostics/TraitProfile';
import { MistakeProfile } from '@/modules/diagnostics/MistakeProfile';
import { SrsQueue } from '@/modules/diagnostics/SrsQueue';

/**
 * v1 routes per architecture-plan.md §2.
 * Phase A scaffolds every module; prose + drill engines author at later phases.
 */
export const router = createBrowserRouter([
  {
    path: '/',
    element: <WorkspaceShell />,
    children: [
      { index: true, element: <ModuleIndex /> },

      // ── M1 Lessons ─────────────────────────────────────────────────────────
      { path: 'lessons', element: <LessonsIndex /> },
      { path: 'lessons/1.13', element: <CapstoneRoute /> },
      { path: 'lessons/:lessonId', element: <Lesson /> },

      // ── M2 Reference ────────────────────────────────────────────────────────
      { path: 'reference', element: <ReferenceIndex /> },
      { path: 'reference/indicators', element: <IndicatorVault /> },
      { path: 'reference/2-part-check', element: <ReferenceSection /> },
      { path: 'reference/fabs', element: <ReferenceSection /> },
      { path: 'reference/stimulus-tendencies', element: <ReferenceSection /> },
      { path: 'reference/conclusion-types', element: <ReferenceSection /> },
      { path: 'reference/rebuttal-structure', element: <ReferenceSection /> },
      { path: 'reference/three-traps', element: <ReferenceSection /> },
      { path: 'reference/pronoun-library', element: <ReferenceSection /> },
      { path: 'reference/concession-decoder', element: <ReferenceSection /> },
      { path: 'reference/quick-card', element: <ReferenceSection /> },
      { path: 'reference/companion-mode', element: <ReferenceSection /> },
      { path: 'reference/named-tools', element: <ReferenceSection /> },
      { path: 'reference/named-tools/:toolId', element: <NamedToolEntry /> },

      // ── M3 Drills ───────────────────────────────────────────────────────────
      { path: 'drills', element: <DrillsIndex /> },
      { path: 'drills/:drillId', element: <DrillShell /> },

      // ── M4 Simulator (gated by Drill 3.4 per §5) ───────────────────────────
      {
        path: 'simulator',
        element: (
          <LockedRoute routeId="/simulator">
            <SimulatorOverview />
          </LockedRoute>
        ),
      },
      {
        path: 'simulator/bank',
        element: (
          <LockedRoute routeId="/simulator/bank">
            <QuestionBank />
          </LockedRoute>
        ),
      },
      {
        path: 'simulator/trap-master',
        element: (
          <LockedRoute routeId="/simulator/trap-master">
            <TrapMaster />
          </LockedRoute>
        ),
      },
      {
        path: 'simulator/trap-master/:traitId',
        element: (
          <LockedRoute routeId="/simulator/trap-master">
            <TraitDeepDive />
          </LockedRoute>
        ),
      },
      {
        path: 'simulator/hard-mode',
        element: (
          <LockedRoute routeId="/simulator/hard-mode">
            <HardMode />
          </LockedRoute>
        ),
      },

      // ── M5 Hard Sentences ───────────────────────────────────────────────────
      { path: 'hard-sentences', element: <HardSentencesIndex /> },
      { path: 'hard-sentences/capstone', element: <CapstoneRoute /> },
      { path: 'hard-sentences/:sectionId', element: <HardSentenceSection /> },

      // ── M6 Diagnostics ──────────────────────────────────────────────────────
      { path: 'diagnostics', element: <DiagnosticsIndex /> },
      { path: 'diagnostics/philosophy', element: <Philosophy /> },
      { path: 'diagnostics/dashboard', element: <Dashboard /> },
      { path: 'diagnostics/recommendations', element: <Recommendations /> },
      { path: 'diagnostics/rr-review', element: <RrReview /> },
      { path: 'diagnostics/trait-profile', element: <TraitProfile /> },
      { path: 'diagnostics/mistake-profile', element: <MistakeProfile /> },
      { path: 'diagnostics/srs', element: <SrsQueue /> },

      // ── Cross-cutting (build at Phase G) ────────────────────────────────────
      { path: 'journal', element: <Placeholder moduleId="—" surfaceLabel="Journal (Phase G)" /> },
      { path: 'settings', element: <Placeholder moduleId="—" surfaceLabel="Settings (Phase G)" /> },

      // 404
      { path: '*', element: <Navigate to="/" replace /> },
    ],
  },
]);

