function deriveSurfaceId(pathname: string): string | null {
  if (pathname.startsWith('/lessons/')) {
    const n = pathname.split('/').pop();
    return n ? `MC-LSN-${n}` : null;
  }
  if (pathname.startsWith('/drills/')) {
    const n = pathname.split('/').pop();
    return n ? `MC-DRL-${n}` : null;
  }
  if (pathname.startsWith('/simulator/bank')) return 'MC-SIM-Q1';
  return null;
}

