  if (stripped.startsWith('/lessons/')) {
    const n = stripped.split('/').pop();
    return n ? `MC-LSN-${n}` : null;
  }
  if (stripped.startsWith('/drills/')) {
    const n = stripped.split('/').pop();
    return n ? `MC-DRL-${n}` : null;
  }
  if (stripped.startsWith('/simulator/bank')) return 'MC-SIM-Q1';
