/**
 * Stub user hook — per architecture-plan.md §3 + handoff §3.A.
 * v1: returns a placeholder anonymous user. LSAT U absorption swaps this with
 * the real auth-backed user; nothing else in the app changes.
 */

import { useEffect, useState } from 'react';
import { getPersistence } from '@/bootcamps/main-conclusion/persistence/factory';
import { TABLES, User } from '@/bootcamps/main-conclusion/persistence/records';
import { now } from '@/bootcamps/main-conclusion/lib/ids';

const STUB_USER_ID = '00000000-0000-4000-8000-000000000001';

export function useUser(): User | null {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const persist = getPersistence(STUB_USER_ID);
      let existing = await persist.get<User>(TABLES.users, STUB_USER_ID);
      if (!existing) {
        existing = User.parse({
          id: STUB_USER_ID,
          name: 'Student',
          started_at: now(),
          last_seen: now(),
          settings: {},
        });
        await persist.set(TABLES.users, STUB_USER_ID, existing);
      } else {
        existing = { ...existing, last_seen: now() };
        await persist.set(TABLES.users, STUB_USER_ID, existing);
      }
      if (!cancelled) setUser(existing);
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  return user;
}

export const STUB_USER_ID_EXPORT = STUB_USER_ID;

