# BSD sed doesn't reliably handle \b. Use explicit boundary chars.
# We match against the chars that legitimately follow a Tailwind class: space, quote, backtick, `.
# Replacing in two passes ensures we don't double-prefix.
find . -type f \( -name '*.ts' -o -name '*.tsx' \) -print0 | xargs -0 perl -i -pe '
  s/\b(text|bg|border|outline|ring|stroke|fill|decoration|placeholder|caret|from|via|to|divide|shadow)-accent-hover\b/\1-mc-accent-hover/g;
  s/\b(text|bg|border|outline|ring|stroke|fill|decoration|placeholder|caret|from|via|to|divide|shadow)-accent-deep\b/\1-mc-accent-deep/g;
  s/\b(text|bg|border|outline|ring|stroke|fill|decoration|placeholder|caret|from|via|to|divide|shadow)-accent\b/\1-mc-accent/g;
  s/\b(text|bg|border)-success\b/\1-mc-success/g;
  s/\b(text|bg|border)-warn\b/\1-mc-warn/g;
  s/\b(text|bg|border)-error\b/\1-mc-error/g;
  s/\b(text|bg|border)-info\b/\1-mc-info/g;
  s/\bfont-sans\b/font-mc-sans/g;
  s/\bfont-serif\b/font-mc-serif/g;
  s/\bfont-mono\b/font-mc-mono/g;
'

echo "After perl rewrite:"
echo "text-mc-accent:" $(grep -roh "text-mc-accent" --include='*.tsx' . | wc -l)
echo "text-accent (should be 0):" $(grep -roh "text-accent[^-]" --include='*.tsx' . | wc -l)
