/* Definition of the design system. All colors, gradients, fonts, etc should be defined here.
All colors MUST be HSL.
*/

@layer base {
  :root {
    color-scheme: dark;

    /* LSAT U — Dark-first design system.
       Tokens resolve to the dark palette by default.
       Add class="light" to <html> to switch to light mode.
    */
    --background: 0 0% 3.9%;         /* neutral-950 */
    --foreground: 0 0% 98%;           /* near white */

    --card: 0 0% 7%;                  /* neutral-900 equivalent */
    --card-foreground: 0 0% 98%;

    --popover: 0 0% 7%;
    --popover-foreground: 0 0% 98%;

    --primary: 0 0% 98%;              /* white — primary interactive on dark */
    --primary-foreground: 0 0% 3.9%; /* dark text behind white elements */

    --secondary: 0 0% 14.9%;          /* neutral-800 */
    --secondary-foreground: 0 0% 98%;

    --muted: 0 0% 14.9%;
    --muted-foreground: 0 0% 63.9%;   /* neutral-500 */

    --accent: 0 0% 14.9%;
    --accent-foreground: 0 0% 98%;

    /* Status colors */
    --success: 142 71% 45%;
    --success-foreground: 0 0% 98%;

    --warning: 38 92% 50%;
    --warning-foreground: 0 0% 98%;

    --destructive: 0 72% 51%;
    --destructive-foreground: 0 0% 98%;

    --border: 0 0% 14.9%;             /* neutral-800 */
    --input: 0 0% 14.9%;
    --ring: 0 0% 83.1%;               /* neutral-300 */

    --radius: 0.5rem;

    /* Shadows */
    --shadow-sm: 0 1px 3px 0 rgba(0, 0, 0, 0.4);
    --shadow: 0 2px 12px 0 rgba(0, 0, 0, 0.5);
    --shadow-md: 0 4px 20px 0 rgba(0, 0, 0, 0.6);
    --shadow-lg: 0 8px 32px 0 rgba(0, 0, 0, 0.7);
    --shadow-glow: 0 0 24px 0 rgba(255, 255, 255, 0.06);

    /* Surface elevation */
    --surface-elevated: 0 0% 10%;

    /* Text hierarchy */
    --text-primary: 0 0% 98%;
    --text-secondary: 0 0% 63.9%;
    --text-tertiary: 0 0% 45%;

    --sidebar-background: 0 0% 3.9%;
    --sidebar-foreground: 0 0% 63.9%;
    --sidebar-primary: 0 0% 98%;
    --sidebar-primary-foreground: 0 0% 3.9%;
    --sidebar-accent: 0 0% 14.9%;
    --sidebar-accent-foreground: 0 0% 98%;
    --sidebar-border: 0 0% 14.9%;
    --sidebar-ring: 0 0% 83.1%;
  }

  /* ── Light mode ── add class="light" to <html> to activate ───────────────── */
  .light {
    color-scheme: light;
    --background: 0 0% 99%;
    --foreground: 0 0% 7%;
    --card: 0 0% 100%;
    --card-foreground: 0 0% 7%;
    --popover: 0 0% 100%;
    --popover-foreground: 0 0% 7%;
    --primary: 0 0% 7%;
    --primary-foreground: 0 0% 99%;
    --secondary: 0 0% 95%;
    --secondary-foreground: 0 0% 7%;
    --muted: 0 0% 95%;
    --muted-foreground: 0 0% 45%;
    --accent: 0 0% 92%;
    --accent-foreground: 0 0% 7%;
    --destructive: 0 72% 51%;
    --destructive-foreground: 0 0% 98%;
    --border: 0 0% 88%;
    --input: 0 0% 90%;
    --ring: 0 0% 20%;
    --surface-elevated: 0 0% 97%;
    --text-primary: 0 0% 7%;
    --text-secondary: 0 0% 45%;
    --text-tertiary: 0 0% 55%;
    --sidebar-background: 0 0% 98%;
    --sidebar-foreground: 0 0% 28%;
    --sidebar-primary: 0 0% 7%;
    --sidebar-primary-foreground: 0 0% 99%;
    --sidebar-accent: 0 0% 92%;
    --sidebar-accent-foreground: 0 0% 7%;
    --sidebar-border: 0 0% 88%;
    --sidebar-ring: 0 0% 20%;
  }

  /* .dark mirrors .light — reserved alias */
  .dark {
    color-scheme: light;
    --background: 0 0% 99%;
    --foreground: 0 0% 7%;
    --card: 0 0% 100%;
    --card-foreground: 0 0% 7%;
    --popover: 0 0% 100%;
    --popover-foreground: 0 0% 7%;
